        function crearTarifaMobile(nombre, atributos, precio, idBtn, index, esActivo = false) {
            const priceFormatted = new Intl.NumberFormat("es-CO").format(precio);
            const esPremium = nombre === "Premium Economy";

            // Clases específicas para mobile
            const cabinaWrapperClass = esPremium ?
                "columnBrandstyle__Brand-sc__sc-1e0tr9m-0 fafSlX premium-cabin PremiumEconomy" :
