                "Light": "cOWaEi",
                "Full": "gksKJ",
                "Premium Economy": "jFkdyd"
            } [nombre] || "cmMa-Dw";

            // Calcular precios según tarifa
            const precioBase = parseInt(precio.toString().replace(/\./g, ""), 10);
            const precioLight = (precioBase + 10000).toLocaleString('es-CO');
