        function generarHorasVuelo() {
            // Hora y minuto de salida aleatorios
            const hSalida24 = Math.floor(Math.random() * 24);
            const mSalida = Math.floor(Math.random() * 60);

            // Duración entre 1h y 3h con minutos
            const duracionHoras = Math.floor(Math.random() * 2) + 1;
            const duracionMinutos = Math.floor(Math.random() * 60);

            // Calcular hora de llegada
            let hLlegada24 = hSalida24 + duracionHoras;
            let mLlegada = mSalida + duracionMinutos;

            if (mLlegada >= 60) {
                mLlegada -= 60;
                hLlegada24 += 1;
            }

            const diaExtra = hLlegada24 >= 24;
            if (hLlegada24 >= 24) hLlegada24 -= 24;

            const format12h = (h24, m) => {
                const period = h24 < 12 ? 'a. m.' : 'p. m.';
                const h12 = h24 % 12 === 0 ? 12 : h24 % 12;
                return `${h12}:${m.toString().padStart(2, '0')} ${period}`;
            };

            const salidaHora = format12h(hSalida24, mSalida);
            const llegadaHora = format12h(hLlegada24, mLlegada) + (diaExtra ? ' +1' : '');

            return {
                salidaHora,
                llegadaHora,
                duracion: `${duracionHoras} h ${duracionMinutos} min`,
            };
        }

