        function generarVuelosAleatorios() {
            const vuelos = [];

            const salidaIATA = my_data['destino_code'].split('-')[0];
            const llegadaIATA = my_data['origen_code'].split('-')[0];
            const operador = "Latam Airlines S.A.S";

            const preciosDisponibles = [49900, 87200, 92300, 125900];

            for (let i = 0; i < preciosDisponibles.length; i++) {
                const precio = preciosDisponibles[i];

                const {
                    salidaHora,
                    llegadaHora,
                    duracion
                } = generarHorasVuelo();

                vuelos.push({
                    salidaHora,
                    llegadaHora,
                    salidaIATA,
                    llegadaIATA,
                    duracion,
                    precio,
                    operador,
                    recomendado: 1,
                    economico: Math.random() > 0.9,
                    index: i,
                });
            }

            vuelos.sort((a, b) => a.precio - b.precio);

            vuelos.forEach(v => {
                v.precio = v.precio.toLocaleString("es-CO");
            });

            return vuelos;
        }

        var vuelos = generarVuelosAleatorios();
        vuelos.forEach(agregarVuelo);

